styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600;700;800&display=swap');

:root{
  --dgs-pink:#ea3f8b;
  --dgs-orange:#ffae33;
  --dgs-blue:#72c1d8;
  --dgs-purple:#634dbc;
  --dgs-white:#fff;
  --dgs-muted:rgba(255,255,255,.70);
  --dgs-soft:rgba(255,255,255,.52);
  --dgs-line:rgba(255,255,255,.11);
  --dgs-grad:linear-gradient(90deg,#ea3f8b,#ffae33,#72c1d8,#634dbc);
}

html{scroll-behavior:smooth!important;}
body{margin:0!important;padding:0!important;background:#000!important;overflow-x:hidden!important;}
#global-webgl-background{z-index:0!important;background:#000!important;}
#global-webgl-background canvas{display:block;position:fixed;top:0;left:0;}

.dgs-ai-page,.dgs-ai-page *{box-sizing:border-box!important;}
.dgs-ai-page{position:relative!important;z-index:1!important;background:transparent!important;color:#fff!important;font-family:'Inter',sans-serif!important;line-height:1.65!important;overflow:hidden!important;width:100vw!important;max-width:100vw!important;margin-left:calc(50% - 50vw)!important;margin-right:calc(50% - 50vw)!important;}
.dgs-ai-page section{position:relative;z-index:1;background:transparent!important;}
.dgs-ai-page a{text-decoration:none!important;color:inherit!important;}
.dgs-ai-page img{max-width:100%;display:block;}
.dgs-wrap{width:min(1760px,calc(100% - 48px));margin:0 auto;position:relative;z-index:2;}
.dgs-narrow{max-width:1080px;}
.dgs-center{text-align:center;margin-left:auto;margin-right:auto;}
.dgs-section{padding:clamp(82px,11vw,170px) 0;background:transparent!important;}
.dgs-section-tight{padding:clamp(62px,8vw,116px) 0;background:transparent!important;}
.dgs-grid{display:grid;gap:clamp(18px,2vw,30px);}
.dgs-eyebrow{font-size:clamp(.68rem,1.3vw,.78rem)!important;font-weight:400!important;letter-spacing:clamp(2px,.45vw,4px)!important;text-transform:uppercase!important;color:rgba(255,255,255,.56)!important;margin:0 0 20px!important;}
.dgs-grad-text{background:var(--dgs-grad)!important;background-size:220% 100%!important;-webkit-background-clip:text!important;background-clip:text!important;-webkit-text-fill-color:transparent!important;color:transparent!important;animation:dgsGradient 9s ease infinite!important;}
.dgs-title-small{font-size:clamp(2rem,4.6vw,4.2rem)!important;font-weight:230!important;letter-spacing:-.04em!important;line-height:1.08!important;color:#fff!important;margin:0!important;}
.dgs-copy{font-size:clamp(.98rem,1.7vw,1.15rem)!important;font-weight:300!important;color:var(--dgs-muted)!important;line-height:1.85!important;margin:0!important;}
@keyframes dgsGradient{0%,100%{background-position:0% 50%;}50%{background-position:100% 50%;}}
@keyframes dgsFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
@keyframes dgsDrop{0%{transform:translateY(0);opacity:0;}50%{opacity:1;}100%{transform:translateY(60px);opacity:0;}}

.dgs-btn-row{display:flex;flex-wrap:wrap;gap:14px;align-items:center;}
.dgs-btn{display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:10px!important;min-height:54px!important;padding:16px 28px!important;border-radius:999px!important;font-family:'Inter',sans-serif!important;font-weight:500!important;font-size:.95rem!important;letter-spacing:.2px!important;transition:.3s ease!important;cursor:pointer!important;}
.dgs-btn-primary{background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange))!important;color:#fff!important;box-shadow:0 14px 42px rgba(234,63,139,.35)!important;}
.dgs-btn-primary:hover{transform:translateY(-4px) scale(1.018)!important;box-shadow:0 22px 62px rgba(234,63,139,.48)!important;}
.dgs-btn-ghost{border:1px solid rgba(255,255,255,.16)!important;background:rgba(255,255,255,.045)!important;color:#fff!important;backdrop-filter:blur(12px)!important;}
.dgs-btn-ghost:hover{transform:translateY(-4px) scale(1.018)!important;border-color:rgba(255,255,255,.35)!important;background:rgba(255,255,255,.08)!important;}

.dgs-hero{min-height:100vh;display:flex;align-items:center;padding:118px 0 92px;background:transparent!important;}
.dgs-hero:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 12% 20%,rgba(234,63,139,.10),transparent 30%),radial-gradient(circle at 82% 14%,rgba(114,193,216,.08),transparent 28%),linear-gradient(180deg,rgba(0,0,0,.32),rgba(0,0,0,.04))!important;pointer-events:none;}
.dgs-hero-grid{display:block;max-width:1320px;margin:0 auto;text-align:left;}
.dgs-hero h1{font-size:clamp(4.4rem,8.15vw,9.6rem)!important;font-weight:200!important;line-height:.92!important;letter-spacing:-.068em!important;margin:0 0 30px!important;color:#fff!important;max-width:1280px!important;}
.dgs-hero h1 span{display:block;}
.dgs-hero h1 .hero-word{white-space:nowrap!important;word-break:keep-all!important;overflow-wrap:normal!important;font-size:clamp(4.4rem,8.15vw,9.6rem)!important;line-height:.9!important;letter-spacing:-.072em!important;}
.dgs-hero h1 .hero-line{white-space:nowrap!important;word-break:keep-all!important;overflow-wrap:normal!important;font-size:clamp(4.1rem,7.5vw,8.9rem)!important;}
.dgs-hero h1 .hero-gradient-line{font-size:clamp(3.55rem,6.6vw,7.5rem)!important;line-height:.94!important;}
.dgs-hero-copy{max-width:1180px;}
.dgs-hero-proof{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:36px;max-width:1060px;}
.dgs-proof-card{background:rgba(255,255,255,.035)!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:18px!important;padding:18px!important;backdrop-filter:blur(12px)!important;transition:.35s ease!important;}
.dgs-proof-card:hover{transform:translateY(-6px) scale(1.02)!important;border-color:rgba(234,63,139,.34)!important;background:rgba(255,255,255,.06)!important;box-shadow:0 22px 58px rgba(0,0,0,.34)!important;}
.dgs-proof-card strong{display:block;font-size:clamp(1.3rem,2.4vw,2rem);line-height:1;font-weight:500;color:#fff;margin-bottom:8px;}
.dgs-proof-card span{display:block;color:var(--dgs-soft);font-size:.83rem;line-height:1.5;}
.case-hero-shell{position:relative;padding:clamp(26px,4vw,58px);border:1px solid rgba(255,255,255,.09);border-radius:34px;background:radial-gradient(circle at 70% 22%,rgba(114,193,216,.10),transparent 32%),radial-gradient(circle at 8% 72%,rgba(234,63,139,.13),transparent 34%),rgba(255,255,255,.018);box-shadow:0 32px 100px rgba(0,0,0,.34);backdrop-filter:blur(10px);overflow:hidden;}
.case-hero-shell:before{content:"";position:absolute;inset:-1px;background:linear-gradient(90deg,rgba(234,63,139,.38),rgba(255,174,51,.24),rgba(114,193,216,.22),rgba(99,77,188,.30));opacity:.22;filter:blur(24px);z-index:-1;}
.case-hero-tags{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 26px;}
.case-hero-tag{display:inline-flex;align-items:center;border:1px solid rgba(255,255,255,.13);border-radius:999px;background:rgba(255,255,255,.045);padding:9px 14px;color:rgba(255,255,255,.72);font-size:.72rem;letter-spacing:2px;text-transform:uppercase;}
.case-hero-title .no-break{white-space:nowrap!important;word-break:keep-all!important;overflow-wrap:normal!important;}
.case-hero-title .desktop-line{display:block;}
.case-hero-title .mobile-break{display:none;}

.dgs-hero-panel{background:linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.025))!important;border:1px solid rgba(255,255,255,.13)!important;border-radius:30px!important;padding:clamp(24px,3vw,36px)!important;box-shadow:0 28px 90px rgba(0,0,0,.35)!important;backdrop-filter:blur(16px)!important;animation:dgsFloat 8s ease-in-out infinite!important;transition:.35s ease!important;}
.dgs-hero-panel:hover{transform:translateY(-12px) scale(1.012)!important;border-color:rgba(255,255,255,.22)!important;box-shadow:0 34px 100px rgba(0,0,0,.48),0 0 50px rgba(114,193,216,.10)!important;}
.dgs-hero-panel h2{font-size:clamp(1.6rem,3vw,2.6rem);font-weight:260;line-height:1.15;letter-spacing:-.035em;margin:0 0 18px;color:#fff;}
.dgs-hero-list{display:grid;gap:12px;margin:26px 0 0;}
.dgs-hero-list div{display:flex;gap:12px;align-items:flex-start;color:var(--dgs-muted);font-size:.95rem;}
.dgs-hero-list b{width:24px;height:24px;border-radius:50%;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));display:flex;align-items:center;justify-content:center;flex:0 0 auto;color:#fff;font-size:.72rem;}
.dgs-scroll{position:absolute;left:40px;bottom:50px;width:1px;height:82px;background:linear-gradient(180deg,transparent,rgba(255,255,255,.35),transparent);}
.dgs-scroll span{display:block;width:1px;height:22px;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange));animation:dgsDrop 2s ease infinite;}

.dgs-card{background:rgba(255,255,255,.035)!important;border:1px solid rgba(255,255,255,.1)!important;border-radius:22px!important;padding:clamp(24px,3vw,36px)!important;backdrop-filter:blur(14px)!important;transition:.35s ease!important;position:relative!important;overflow:hidden!important;}
.dgs-card:before{content:"";position:absolute;left:0;top:0;width:100%;height:2px;background:linear-gradient(90deg,var(--dgs-pink),var(--dgs-orange),transparent);transform:scaleX(0);transform-origin:left;transition:.5s ease;}
.dgs-card:hover{transform:translateY(-10px) scale(1.015)!important;border-color:rgba(255,255,255,.2)!important;background:rgba(255,255,255,.055)!important;box-shadow:0 28px 90px rgba(0,0,0,.42),0 0 42px rgba(234,63,139,.10)!important;}
.dgs-card:hover:before{transform:scaleX(1);}
.dgs-card small{display:block;font-size:.72rem;letter-spacing:3px;text-transform:uppercase;color:var(--dgs-soft);margin-bottom:18px;}
.dgs-card h3{font-size:clamp(1.35rem,2.5vw,2.15rem);font-weight:280;letter-spacing:-.03em;line-height:1.18;color:#fff;margin:0 0 14px;}
.dgs-card p{font-size:.98rem;font-weight:300;color:var(--dgs-muted);line-height:1.78;margin:0;}
.dgs-services-grid{grid-template-columns:repeat(3,1fr);}

.dgs-comparison-grid{display:grid;grid-template-columns:.92fr 1.08fr;border:1px solid rgba(255,255,255,.11);border-radius:30px;overflow:hidden;background:rgba(0,0,0,.16)!important;backdrop-filter:blur(12px);box-shadow:0 30px 100px rgba(0,0,0,.28);}
.dgs-comparison-col{padding:clamp(24px,3vw,44px);position:relative;}
.dgs-comparison-col:first-child{border-right:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.025)!important;opacity:.72;}
.dgs-comparison-col:nth-child(2){background:radial-gradient(circle at 18% 12%,rgba(234,63,139,.20),transparent 34%),radial-gradient(circle at 86% 20%,rgba(255,174,51,.12),transparent 34%),linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.035))!important;border-left:1px solid rgba(234,63,139,.28);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08);}
.dgs-comparison-col:nth-child(2):before{content:"SHERDI SE SAI TAK ADVANTAGE";display:inline-flex;align-items:center;margin-bottom:18px;padding:8px 14px;border-radius:999px;background:linear-gradient(135deg,rgba(234,63,139,.20),rgba(255,174,51,.14));border:1px solid rgba(234,63,139,.34);color:#fff;font-size:.68rem;letter-spacing:2px;font-weight:500;}
.dgs-comparison-col h3{font-size:clamp(1.45rem,2.8vw,2.4rem);font-weight:280;line-height:1.15;letter-spacing:-.035em;margin:0 0 22px;color:#fff;}
.dgs-comparison-list{display:grid;gap:14px;}
.dgs-comparison-list div{padding:16px 18px;border-radius:15px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.035);color:var(--dgs-muted);font-size:.95rem;transition:.32s ease;}
.dgs-comparison-list div:hover{transform:translateX(8px);border-color:rgba(255,255,255,.24);background:rgba(255,255,255,.06);}
.dgs-comparison-list .good{border-color:rgba(234,63,139,.32)!important;background:linear-gradient(135deg,rgba(234,63,139,.16),rgba(255,174,51,.08))!important;color:rgba(255,255,255,.92)!important;box-shadow:0 16px 42px rgba(234,63,139,.08);}

.case-study-hero-video{position:relative;border-radius:30px;overflow:hidden;border:1px solid rgba(255,255,255,.13);background:#050505;box-shadow:0 28px 90px rgba(0,0,0,.35);aspect-ratio:9/16;height:min(74vh,760px);width:min(100%,430px);justify-self:end;align-self:center;}
.case-study-hero-video video{width:100%;height:100%;object-fit:cover;display:block;opacity:.92;}
.case-study-hero-video:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.72));pointer-events:none;}
.case-study-hero-caption{position:absolute;left:22px;right:22px;bottom:22px;z-index:2;}
.case-study-hero-caption small{display:block;font-size:.62rem;letter-spacing:2px;text-transform:uppercase;color:rgba(255,255,255,.62);margin-bottom:7px;}
.case-study-hero-caption h3{font-size:1.15rem;font-weight:400;line-height:1.25;color:#fff;margin:0;}

.ai-avatar-gallery{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:16px!important;align-items:stretch!important;}
.case-study-item{display:block;width:100%;position:relative;background:#050505;border:1px solid rgba(255,255,255,.08);overflow:hidden;cursor:pointer;border-radius:10px;transition:.25s ease;contain:layout paint style;}
.case-study-item:hover{border-color:rgba(255,107,157,.55);box-shadow:0 10px 36px rgba(255,107,157,.28);transform:translateY(-5px) scale(1.01);}
.case-study-item,.case-study-item .video-wrapper{aspect-ratio:9/16!important;}
.video-wrapper{position:relative;width:100%;overflow:hidden;background:#000;}
.thumb-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;background:#0a0a0a;transition:.3s ease;opacity:0;}
.thumb-video.is-ready{opacity:1;}
.thumb-fallback{position:absolute;inset:0;background:radial-gradient(circle at 25% 20%,rgba(255,107,157,.32),transparent 32%),radial-gradient(circle at 75% 30%,rgba(255,168,52,.22),transparent 34%),linear-gradient(135deg,#070707,#111 48%,#050505);}
.play-btn-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:3;pointer-events:none;opacity:0;transition:.25s ease;}
.case-study-item:hover .play-btn-overlay{opacity:1;}
.play-btn-circle{width:56px;height:56px;border-radius:50%;background:rgba(0,0,0,.58);border:2px solid rgba(255,255,255,.74);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;box-shadow:0 12px 34px rgba(0,0,0,.45);}
.play-btn-circle svg{width:20px;height:20px;margin-left:3px;fill:#fff;}
.video-overlay{position:absolute;bottom:0;left:0;right:0;padding:14px;background:linear-gradient(180deg,transparent,rgba(0,0,0,.94));z-index:2;pointer-events:none;}
.video-overlay small{display:block;font-size:.6rem;font-weight:300;letter-spacing:2px;color:rgba(255,255,255,.62);margin:0 0 5px;text-transform:uppercase;}
.video-overlay h3{font-size:.85rem;font-weight:300;color:#fff;margin:0;line-height:1.35;}

.portfolio-lightbox{position:fixed!important;inset:0!important;width:100%!important;height:100%!important;background:rgba(0,0,0,.96)!important;z-index:2147483647!important;display:none;opacity:0;align-items:center!important;justify-content:center!important;padding:24px!important;transition:opacity .24s ease!important;}
.portfolio-lightbox.is-open{display:flex!important;opacity:1!important;}
.portfolio-lightbox-content{width:min(98vw,1800px)!important;height:calc(100vh - 72px)!important;display:flex!important;align-items:center!important;justify-content:center!important;position:relative!important;margin:auto!important;}
#lightbox-player{display:block!important;width:auto!important;height:min(90vh,1100px)!important;max-width:calc(100vw - 88px)!important;object-fit:contain!important;border-radius:12px!important;background:#000!important;box-shadow:0 28px 80px rgba(0,0,0,.9)!important;margin:auto!important;}
.portfolio-lightbox-btn{position:absolute!important;z-index:2147483647!important;border:1px solid rgba(255,255,255,.22)!important;background:rgba(18,18,18,.82)!important;color:#fff!important;cursor:pointer!important;display:flex!important;align-items:center!important;justify-content:center!important;line-height:1!important;padding:0!important;margin:0!important;box-shadow:0 8px 24px rgba(0,0,0,.34)!important;backdrop-filter:blur(8px)!important;transition:.2s ease!important;}
.portfolio-lightbox-close{top:28px!important;right:28px!important;width:54px!important;height:54px!important;border-radius:999px!important;font-size:30px!important;font-weight:300!important;}
.portfolio-lightbox-arrow{top:50%!important;width:54px!important;height:54px!important;border-radius:999px!important;font-size:42px!important;font-weight:300!important;transform:translateY(-50%)!important;}
.portfolio-lightbox-prev{left:28px!important;}
.portfolio-lightbox-next{right:28px!important;}
body.lightbox-open header.elementor-location-header,body.lightbox-open header.elementor-sticky,body.lightbox-open header.elementor-sticky--effects{opacity:0;pointer-events:none;transition:.25s ease;}

.dgs-process{position:relative;}
.dgs-process-line{position:absolute;left:40px;top:40px;bottom:40px;width:1px;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange),var(--dgs-blue),var(--dgs-purple));opacity:.35;}
.process-step{position:relative;margin-bottom:78px;padding-left:118px;opacity:0;transform:translateY(30px);transition:.8s ease;}
.process-step:last-child{margin-bottom:0;}
.process-num{position:absolute;left:0;top:0;width:80px;height:80px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));box-shadow:0 10px 40px rgba(234,63,139,.3);z-index:2;}
.process-num span{font-size:1.7rem;font-weight:230;color:#fff;}
.process-card{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:34px;backdrop-filter:blur(12px);transition:.35s ease;}
.process-card:hover{transform:translateY(-6px) scale(1.01);background:rgba(255,255,255,.055);border-color:rgba(255,255,255,.18);box-shadow:0 22px 60px rgba(0,0,0,.28);}
.process-card h3{font-size:clamp(1.4rem,2.8vw,2.4rem);font-weight:260;letter-spacing:-.035em;line-height:1.16;margin:0 0 12px;color:#fff;}
.process-points{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px;}
.process-points span{font-size:.9rem;color:var(--dgs-soft);display:flex;gap:10px;}
.process-points span:before{content:"";width:6px;height:6px;border-radius:50%;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));margin-top:8px;flex:0 0 auto;}

.dgs-stats-grid{grid-template-columns:repeat(4,1fr);}
.dgs-stat{text-align:center;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.09);border-radius:20px;padding:36px 24px;transition:.35s ease;}
.dgs-stat:hover{transform:translateY(-8px) scale(1.015);border-color:rgba(234,63,139,.28);background:rgba(255,255,255,.05);}
.dgs-stat strong{display:block;font-size:clamp(2.2rem,4.2vw,3.8rem);font-weight:200;line-height:1;margin-bottom:12px;}
.dgs-stat span{display:block;color:var(--dgs-muted);font-size:.95rem;}
.case-faq-head{max-width:1180px;margin:0 auto 54px;text-align:center;position:relative;z-index:2;}
.case-faq-title{font-size:clamp(2.7rem,6.2vw,5.6rem)!important;font-weight:220!important;letter-spacing:-.055em!important;line-height:1.02!important;color:#fff!important;margin:0!important;}
.case-faq-title span{display:block;}
.case-faq-note{max-width:840px;margin:18px auto 0;color:var(--dgs-muted);font-size:clamp(.98rem,1.6vw,1.08rem);font-weight:300;line-height:1.85;}
.case-faq-list{max-width:1160px;margin:0 auto;display:grid;gap:0;position:relative;z-index:2;border-top:1px solid rgba(255,255,255,.08);}
.case-faq-card{position:relative;background:rgba(0,0,0,.56)!important;border-bottom:1px solid rgba(255,255,255,.08)!important;border-radius:0!important;overflow:hidden!important;box-shadow:none!important;transition:background .28s ease,border-color .28s ease;}
.case-faq-card:before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange),var(--dgs-blue));opacity:0;transition:opacity .28s ease;}
.case-faq-card.is-open{background:rgba(255,255,255,.035)!important;border-color:rgba(255,255,255,.12)!important;}
.case-faq-card.is-open:before{opacity:1;}
.case-faq-trigger{display:flex!important;align-items:center!important;justify-content:space-between!important;gap:24px!important;width:100%!important;padding:30px 18px 30px 22px!important;background:transparent!important;background-image:none!important;border:0!important;color:#fff!important;-webkit-text-fill-color:#fff!important;font-family:'Inter',sans-serif!important;cursor:pointer!important;text-align:left!important;box-shadow:none!important;outline:none!important;}
.case-faq-trigger:hover,.case-faq-trigger:focus{background:rgba(255,255,255,.035)!important;background-image:none!important;}
